from pathlib import Path

gradle = Path("android/app/build.gradle.kts")

if not gradle.exists():
    raise SystemExit(
        "Expected android/app/build.gradle.kts was not generated by Flutter."
    )

text = gradle.read_text()

if "resValues = true" not in text:
    marker = "android {"

    if marker not in text:
        raise SystemExit("Could not find android block.")

    text = text.replace(
        marker,
        marker + """
    buildFeatures {
        resValues = true
    }
""",
        1
    )

if "flavorDimensions" not in text:
    flavor_block = '''
    flavorDimensions += "edition"
    productFlavors {
        create("lite") {
            dimension = "edition"
            applicationIdSuffix = ".lite"
            resValue("string", "app_name", "ORLI Lite")
        }
        create("pro") {
            dimension = "edition"
            applicationIdSuffix = ".pro"
            resValue("string", "app_name", "ORLI Pro")
        }
    }
'''
    text = text.replace("android {", "android {" + flavor_block, 1)

gradle.write_text(text)
